// Fatia um PDF de 1 página muito comprida (print de app salvo em PDF) em várias páginas
// usando uma atualização incremental (mesmo conteúdo, MediaBox diferente por página).
function fatiarPdf(b64) {
  const buf = Buffer.from(b64, 'base64');
  const s = buf.toString('latin1');
  const out = { b64, paginas: 1, fatiado: false };
  if (/\/ObjStm|\/Type\s*\/XRef/.test(s)) return out;
  const pags = s.match(/\/Type\s*\/Page(?![a-zA-Z])/g) || [];
  if (pags.length !== 1) return out;
  const mPage = /(\d+)\s+0\s+obj\s*<<((?:(?!endobj)[\s\S])*?\/Type\s*\/Page(?![a-zA-Z])(?:(?!endobj)[\s\S])*?)>>\s*endobj/.exec(s);
  if (!mPage) return out;
  const dict = mPage[2];
  const mb = /\/MediaBox\s*\[\s*([-\d.]+)\s+([-\d.]+)\s+([-\d.]+)\s+([-\d.]+)\s*\]/.exec(dict) || /\/MediaBox\s*\[\s*([-\d.]+)\s+([-\d.]+)\s+([-\d.]+)\s+([-\d.]+)\s*\]/.exec(s);
  if (!mb) return out;
  const [x0, y0, x1, y1] = mb.slice(1, 5).map(Number);
  const W = x1 - x0, H = y1 - y0;
  if (!(W > 0 && H / W > 2.2)) return out;
  const res = /\/Resources\s+(\d+\s+0\s+R)/.exec(dict);
  const cont = /\/Contents\s+(\d+\s+0\s+R|\[[^\]]*\])/.exec(dict);
  if (!res || !cont) return out;
  const tr = s.lastIndexOf('trailer');
  const size = Number((/\/Size\s+(\d+)/.exec(s.slice(tr)) || [])[1]);
  const prev = Number((/startxref\s+(\d+)/.exec(s.slice(s.lastIndexOf('startxref'))) || [])[1]);
  if (!size || !prev) return out;
  const alto = W * 1.45, sobra = Math.min(24, alto * 0.05);
  const fatias = [];
  for (let topo = y1; topo > y0 + 1; topo -= (alto - sobra)) {
    const base = Math.max(y0, topo - alto);
    fatias.push([x0, base, x1, topo]);
    if (base <= y0) break;
    if (fatias.length >= 80) break;
  }
  const nPages = size, nCat = size + 1, prim = size + 2;
  const objs = [];
  const kids = fatias.map((_, i) => (prim + i) + ' 0 R').join(' ');
  objs.push([nPages, '<< /Type /Pages /Kids [ ' + kids + ' ] /Count ' + fatias.length + ' >>']);
  objs.push([nCat, '<< /Type /Catalog /Pages ' + nPages + ' 0 R >>']);
  fatias.forEach((f, i) => {
    const box = '[ ' + f.map(v => Number(v.toFixed(2))).join(' ') + ' ]';
    objs.push([prim + i, '<< /Type /Page /Parent ' + nPages + ' 0 R /MediaBox ' + box + ' /CropBox ' + box + ' /Resources ' + res[1] + ' /Contents ' + cont[1] + ' >>']);
  });
  let txt = s.endsWith('\n') ? '' : '\n';
  let pos = buf.length + txt.length;
  const offs = [];
  for (const [n, d] of objs) {
    const o = n + ' 0 obj\n' + d + '\nendobj\n';
    offs.push([n, pos]);
    txt += o; pos += o.length;
  }
  const xref = pos;
  txt += 'xref\n' + nPages + ' ' + objs.length + '\n' + offs.map(([, p]) => String(p).padStart(10, '0') + ' 00000 n \n').join('');
  txt += 'trailer\n<< /Size ' + (prim + fatias.length) + ' /Root ' + nCat + ' 0 R /Prev ' + prev + ' >>\nstartxref\n' + xref + '\n%%EOF\n';
  const novo = Buffer.concat([buf, Buffer.from(txt, 'latin1')]);
  return { b64: novo.toString('base64'), paginas: fatias.length, fatiado: true };
}

