- Se o arquivo não for extrato nem fatura, tipo_documento "outro" e lancamentos vazio.
- Confira no fim: a quantidade de lançamentos devolvidos deve bater com as linhas do documento; não pule páginas.".replace('HOJE', hoje);
const schema = {"type": "object", "additionalProperties": false, "required": ["tipo_documento", "instituicao", "periodo_inicio", "periodo_fim", "vencimento", "lancamentos"], "properties": {"tipo_documento": {"type": "string", "enum": ["extrato_conta", "fatura_cartao", "outro"]}, "instituicao": {"type": ["string", "null"]}, "periodo_inicio": {"type": ["string", "null"]}, "periodo_fim": {"type": ["string", "null"]}, "vencimento": {"type": ["string", "null"]}, "lancamentos": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["data", "descricao", "valor", "movimento", "categoria", "forma_pagamento", "ignorar", "motivo", "parcela_atual", "parcelas_total"], "properties": {"data": {"type": "string"}, "descricao": {"type": "string"}, "valor": {"type": "number"}, "movimento": {"type": "string", "enum": ["despesa", "receita"]}, "categoria": {"type": "string", "enum": ["alimentacao", "mercado", "transporte", "combustivel", "moradia", "contas", "saude", "lazer", "educacao", "compras", "assinaturas", "viagem", "trabalho", "impostos", "outros", "salario", "vendas", "freelance", "reembolso", "investimentos"]}, "forma_pagamento": {"type": ["string", "null"]}, "ignorar": {"type": "boolean"}, "motivo": {"type": ["string", "null"]}, "parcela_atual": {"type": ["integer", "null"]}, "parcelas_total": {"type": ["integer", "null"]}}}}}};
