const exist = $('Lançamentos existentes').all().map(i => i.json).filter(r => r && r.id != null && (r.autor || 'Daniel') === p.autor)
  .map(r => ({ v: Number(r.valor) || 0, tipo: r.tipo === 'receita' ? 'receita' : 'despesa', d: DateTime.fromISO(String(r.data)).setZone('America/Sao_Paulo'), parc: /parcela|\b\d{1,2}\s*\/\s*\d{1,2}\b/i.test(String(r.descricao || '')), num: ((/(\d{1,2})\s*\/\s*(\d{1,2})/.exec(String(r.descricao || '')) || []).slice(1, 3).join('/')), usado: false }));
// 07/10: compras parceladas. A parcela 2/10 em diante entra na data de referência da fatura (fechamento), não na data da compra
