const ehFatura = L.doc && L.doc.tipo === 'fatura_cartao';
const datasVista = L.lanc.filter(l => !l.ignorar && !(Number(l.parcela_atual) > 1)).map(l => l.data).sort();
const okData = s => /^\d{4}-\d{2}-\d{2}/.test(String(s || '')) && DateTime.fromISO(String(s).slice(0, 10)).isValid;
const refFatura = okData(L.doc && L.doc.ate) ? String(L.doc.ate).slice(0, 10) : (datasVista.length ? datasVista[datasVista.length - 1] : null);
const limpaParc = t => String(t || '').replace(/\s*\(?\s*parc(ela)?\.?\s*\d{1,2}\s*(\/|de)\s*\d{1,2}\s*\)?/ig, '').replace(/\s+\d{1,2}\s*\/\s*\d{1,2}\s*$/, '').trim();
