  let m = exist.find(e => !e.usado && e.tipo === l.movimento && Math.abs(e.v - Number(l.valor)) < 0.011 && e.d.isValid && Math.abs(e.d.diff(d, 'days').days) <= 2.5);
  if (!m && l.parc) {
    const cands = exist.filter(e => !e.usado && e.parc && e.tipo === l.movimento && Math.abs(e.v - Number(l.valor)) < 0.011 && e.d.isValid && Math.abs(e.d.diff(d, 'days').days) <= 20);
    const alvo = l.parc.a + '/' + l.parc.t;
    m = cands.find(e => e.num === alvo) || (cands.some(e => e.num) ? null : cands.sort((x, y) => Math.abs(x.d.diff(d).as('days')) - Math.abs(y.d.diff(d).as('days')))[0]) || null;
