const porCat = {};
gastos.forEach(l => { porCat[l.categoria] = (porCat[l.categoria] || 0) + Number(l.valor); });
const topCat = Object.entries(porCat).sort((a, b) => b[1] - a[1]).slice(0, 4).map(([c, v]) => cat(c) + ' ' + brl(v)).join(' · ');
const maiores = gastos.slice().sort((a, b) => b.valor - a.valor).slice(0, 5).map(l => '• ' + dbr(l.data) + ' ' + String(l.descricao).slice(0, 40) + ' — ' + brl(l.valor)).join(NL);
const titulo = (L.doc.tipo === 'fatura_cartao' ? 'Fatura do cartão' : 'Extrato da conta') + (L.doc.instituicao ? ' ' + L.doc.instituicao : '') + (L.doc.de && L.doc.ate ? ' (' + dbr(L.doc.de) + ' a ' + dbr(L.doc.ate) + ')' : '');
const linhas = ['📄 *' + titulo + '*', '', 'Encontrei *' + L.lanc.length + ' lançamentos*:'];
linhas.push('• ' + novos.length + (novos.length === 1 ? ' novo' : ' novos') + (novos.length ? ': ' + brl(soma(gastos)) + ' em gastos' + (entradas.length ? ' e ' + brl(soma(entradas)) + ' em entradas' : '') : ''));
if (dup.length) linhas.push('• ' + dup.length + (dup.length === 1 ? ' já estava' : ' já estavam') + ' no Dyno (não vou duplicar)');
if (ignorados.length) linhas.push('• ' + ignorados.length + (ignorados.length === 1 ? ' ignorado' : ' ignorados') + ' (pagamento de fatura, saldos, transferências entre suas contas ou investimentos)');
